(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('productivity-kit', {
    meta: {
      name: 'Productivity Kit',
      type: 'Kit',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Essential productivity tools: priority badges, due dates, and task completion tracking'
    },

    onAppInit(ctx) {
      ctx.logger.log('Productivity Kit initialized');
      this.loadSettings();
    },

    loadSettings() {
      this.settings = {
        enablePriority: true,
        enableDueDates: true,
        enableCompletion: true
      };
    },

    // Priority system
    getPriority(card) {
      const priorityTags = ['urgent', 'high', 'medium', 'low'];
      for (const tag of priorityTags) {
        if (card.tags && card.tags.includes(tag)) {
          return tag;
        }
      }
      return null;
    },

    getPriorityEmoji(priority) {
      const emojis = {
        'urgent': '🔴',
        'high': '🟠',
        'medium': '🟡',
        'low': '🟢'
      };
      return emojis[priority] || '';
    },

    // Due date system
    getDueDate(card) {
      if (!card.modsData || !card.modsData['productivity-kit']) return null;
      return card.modsData['productivity-kit'].dueDate;
    },

    isOverdue(dueDate) {
      if (!dueDate) return false;
      const due = new Date(dueDate);
      const now = new Date();
      return due < now;
    },

    formatDueDate(dueDate) {
      const due = new Date(dueDate);
      const now = new Date();
      const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));

      if (diffDays < 0) return `Overdue by ${Math.abs(diffDays)} day${Math.abs(diffDays) !== 1 ? 's' : ''}`;
      if (diffDays === 0) return 'Due today';
      if (diffDays === 1) return 'Due tomorrow';
      return `Due in ${diffDays} days`;
    },

    // Completion tracking
    isCompleted(card) {
      return card.tags && card.tags.includes('completed');
    },

    onCardRender(ctx, card, element) {
      // Add priority badge
      if (this.settings.enablePriority) {
        const priority = this.getPriority(card);
        if (priority) {
          const badge = document.createElement('span');
          badge.className = `priority-badge priority-${priority}`;
          badge.textContent = `${this.getPriorityEmoji(priority)} ${priority.toUpperCase()}`;
          badge.title = `Priority: ${priority}`;

          const titleElement = element.querySelector('.card-title');
          if (titleElement) {
            titleElement.appendChild(badge);
          }
        }
      }

      // Add due date indicator
      if (this.settings.enableDueDates) {
        const dueDate = this.getDueDate(card);
        if (dueDate) {
          const dueDateBadge = document.createElement('div');
          dueDateBadge.className = 'due-date-badge';
          if (this.isOverdue(dueDate)) {
            dueDateBadge.classList.add('overdue');
          }
          dueDateBadge.innerHTML = `
            <span class="due-date-icon">📅</span>
            <span class="due-date-text">${this.formatDueDate(dueDate)}</span>
          `;
          element.appendChild(dueDateBadge);
        }
      }

      // Add completion styling
      if (this.settings.enableCompletion) {
        if (this.isCompleted(card)) {
          element.classList.add('task-completed');

          const completedBadge = document.createElement('span');
          completedBadge.className = 'completed-badge';
          completedBadge.textContent = '✓ COMPLETED';

          const titleElement = element.querySelector('.card-title');
          if (titleElement) {
            titleElement.appendChild(completedBadge);
          }
        }
      }
    },

    async onCardSave(ctx, card, saveInfo) {
      // Auto-add priority based on keywords if not set
      const hasUrgentKeywords = /\b(asap|urgent|critical|emergency)\b/i.test(card.body);
      if (hasUrgentKeywords && !this.getPriority(card)) {
        await ctx.utils.addTag(card.id, 'urgent');
      }
    }
  });
})();

