/* Priority badges */
.priority-badge {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 0.7em;
  font-weight: bold;
  color: white;
}

.priority-urgent {
  background: #f44336;
  animation: pulse-urgent 2s infinite;
}

.priority-high {
  background: #ff9800;
}

.priority-medium {
  background: #ffc107;
  color: #333;
}

.priority-low {
  background: #4caf50;
}

@keyframes pulse-urgent {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

/* Due date badges */
.due-date-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  padding: 6px 10px;
  background: var(--bg-hover);
  border-left: 3px solid #2196f3;
  border-radius: 4px;
  font-size: 0.85em;
}

.due-date-badge.overdue {
  background: rgba(244, 67, 54, 0.1);
  border-left-color: #f44336;
}

.due-date-icon {
  font-size: 1.1em;
}

.due-date-text {
  font-weight: 500;
}

.due-date-badge.overdue .due-date-text {
  color: #f44336;
  font-weight: bold;
}

/* Completed tasks */
.task-completed {
  opacity: 0.6;
}

.task-completed .card-title {
  text-decoration: line-through;
}

.completed-badge {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 8px;
  background: #4caf50;
  color: white;
  border-radius: 12px;
  font-size: 0.7em;
  font-weight: bold;
}
